import { mkdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { readMigrationFiles } from "drizzle-orm/migrator";

const migrationRoot = new URL("../drizzle/", import.meta.url);
const journal = JSON.parse(await readFile(new URL("meta/_journal.json", migrationRoot), "utf8"));
const migrations = readMigrationFiles({ migrationsFolder: fileURLToPath(migrationRoot) });
const output = new URL("../deploy/hostinger-empty-database.sql", import.meta.url);
const lines = [
  "-- GENERATED by npm run db:export-hostinger from the canonical Drizzle journal.",
  "-- Import ONCE into an EMPTY selected database using phpMyAdmin. No customer data or credentials.",
  "-- Stop on the first SQL error. MySQL DDL is not transactionally rolled back.",
  "-- Do not import into an existing/partially migrated database or disable foreign-key checks.",
  "-- Migration hashes/timestamps below preserve compatibility with npm run db:migrate.",
  "CREATE TABLE `__drizzle_migrations` (`id` SERIAL PRIMARY KEY, `hash` text NOT NULL, `created_at` bigint);",
];
for (const [index, migration] of migrations.entries()) {
  lines.push(`\n-- ${journal.entries[index].tag}`);
  for (const statement of migration.sql) {
    const sql = statement.trim();
    if (sql) lines.push(sql.endsWith(";") ? sql : `${sql};`);
  }
  lines.push(`INSERT INTO \`__drizzle_migrations\` (\`hash\`, \`created_at\`) VALUES ('${migration.hash}', ${migration.folderMillis});`);
}
await mkdir(new URL("../deploy/", import.meta.url), { recursive: true });
await writeFile(output, `${lines.join("\n")}\n`);
console.log(`Exported ${migrations.length} migrations to deploy/hostinger-empty-database.sql.`);
